parameters.query:
-- Get current data statistics before cleanup
SELECT 
    'Before Cleanup' as phase,
    (
        SELECT COUNT(*) FROM health_reports
    ) as total_health_reports,
    (
        SELECT COUNT(*) FROM alert_history
    ) as total_alert_history,
    (
        SELECT COUNT(*) FROM health_reports 
        WHERE checked_at < DATE_SUB(NOW(), INTERVAL (
            SELECT CAST(config_value AS UNSIGNED) FROM config WHERE config_key = 'data_retention_days'
        ) DAY)
    ) as old_health_reports,
    (
        SELECT COUNT(*) FROM alert_history 
        WHERE sent_at < DATE_SUB(NOW(), INTERVAL (
            SELECT CAST(config_value AS UNSIGNED) FROM config WHERE config_key = 'data_retention_days'
        ) DAY)
    ) as old_alert_history,
    (
        SELECT config_value FROM config WHERE config_key = 'data_retention_days'
    ) as retention_days,
    NOW() as timestamp;

-- Get statistics after cleanup
SELECT 
    'After Cleanup' as phase,
    (
        SELECT COUNT(*) FROM health_reports
    ) as total_health_reports,
    (
        SELECT COUNT(*) FROM alert_history
    ) as total_alert_history,
    (
        SELECT ROUND(
            (SELECT SUM(data_length + index_length) FROM information_schema.tables 
             WHERE table_schema = DATABASE() AND table_name IN ('health_reports', 'alert_history')
            ) / 1024 / 1024, 2
        )
    ) as database_size_mb,
    NOW() as timestamp;

